async function scanPorts(forceChooser=false){
  try {
    const ports=forceChooser?await window.bridge.choosePort():await window.bridge.ports(),select=$('port-select'),previous=select.value;
    const preferred=ports.find(p=>/espressif/i.test(p.manufacturer)||p.vendorId?.toLowerCase()==='303a')||ports.find(p=>/usb(modem|serial)/i.test(p.path));
    select.replaceChildren();
    const placeholder=document.createElement('option');placeholder.value='';placeholder.textContent=ports.length?'Select USB port':'No serial ports found';select.append(placeholder);
    for(const p of ports){const option=document.createElement('option');option.value=p.path;option.textContent=`${p.path}${p.manufacturer?' · '+p.manufacturer:''}`;select.append(option);}
    if(ports.some(p=>p.path===previous))select.value=previous;
    else if(preferred)select.value=preferred.path;
    else if(ports.length===1)select.value=ports[0].path;
    const hint=$('port-discovery');
    hint.className=`port-discovery ${preferred?'found':ports.length?'':'warning'}`;
    hint.textContent=preferred?`ESP32 USB device detected: ${preferred.path}. Close Arduino Serial Monitor before connecting.`:ports.length?'Choose a serial port, then connect.':'No USB serial device detected. Check the cable and reconnect the bridge.';
    setButtons();
  } catch(error){$('port-discovery').textContent=`Port scan failed: ${error.message}`;$('port-discovery').className='port-discovery warning';}
}
