new ResizeObserver(updateFrameScale).observe($('canvas-wrap'));
$('wifi-form').onsubmit=e=>{e.preventDefault();const data=new FormData(e.target);act(async()=>{await window.bridge.wifi(data.get('ssid'),data.get('password'));toast('Wi-Fi connection requested. Waiting for the bridge result.');});};$('mqtt-form').onsubmit=e=>{e.preventDefault();const data=new FormData(e.target);act(async()=>{await window.bridge.mqtt(data.get('host'),+data.get('port'),data.get('root'),data.get('user'),data.get('password'));toast('MQTT connection requested. Waiting for the bridge result.');});};
$('viewer-form').onsubmit=e=>{e.preventDefault();armSound();const data=new FormData(e.target);act(async()=>{await window.bridge.monitorSave({host:data.get('host'),port:+data.get('port'),root:data.get('root'),user:data.get('user'),password:data.get('password')});viewerStates={};renderViewer();toast('MQTT viewer settings saved. Connecting…');});};
$('viewer-forget').onclick=()=>act(async()=>{await window.bridge.monitorForget();$('viewer-form').reset();viewerStates={};renderViewer();toast('MQTT viewer settings removed from this computer.');});
$('forget-wifi').onclick=()=>act(async()=>{await window.bridge.forgetWifi();$('wifi-form').reset();toast('Wi-Fi settings forgotten on the bridge.');});
$('forget-mqtt').onclick=()=>act(async()=>{await window.bridge.forgetMqtt();$('mqtt-form').reset();toast('MQTT settings forgotten on the bridge.');});
$('refresh-diagnostics').onclick=()=>act(()=>window.bridge.logs());
$('clear-diagnostics').onclick=()=>{diagnosticEvents=[];localStorage.removeItem('diagnosticEvents');renderDiagnostics();};
window.bridge.on('bridge:diagnostic',addDiagnostic);
window.bridge.on('monitor:status',event=>{const previous=viewerStatus;viewerStatus=event.status;viewerDetail=event.detail;viewerBridgeOnline=event.bridgeOnline;if(event.settings){const form=$('viewer-form');for(const key of ['host','port','root','user'])form.elements[key].value=event.settings[key]||'';}if(viewerStatus!=='connected'){clearTimeout(viewerPruneTimer);if(previous==='connected')viewerStates={};}else if(previous!=='connected'){viewerPruneTimer=setTimeout(()=>{if(viewerStatus!=='connected')return;viewerHistory=viewerHistory.filter(item=>viewerStates[item.topic]);saveViewerHistory();renderViewer();},5000);}renderViewer();if(liveSensors&&liveSource==='mqtt'){drawOverlay();renderSensors();}});
window.bridge.on('monitor:message',event=>{const previous=viewerStates[event.topic]?.value;viewerStates[event.topic]=event;if(!event.retained&&previous!==event.value){viewerHistory.unshift({...event,previous});viewerHistory=viewerHistory.slice(0,300);saveViewerHistory();if(changedKnownState(previous,event.value))playStateChime();}renderViewer();if(liveSensors&&liveSource==='mqtt'){drawOverlay();renderSensors();}});
window.bridge.on('monitor:removed',event=>{delete viewerStates[event.topic];viewerHistory=viewerHistory.filter(item=>item.topic!==event.topic);saveViewerHistory();renderViewer();if(liveSensors&&liveSource==='mqtt'){drawOverlay();renderSensors();}});
window.bridge.on('bridge:state',data=>{rememberCameras(data);if(!data.connected){data.configs=Object.fromEntries(Object.entries(knownCameras).map(([mac,item])=>[mac,cloneConfig(item.config)]));data.cameras=Object.values(knownCameras).map(item=>({...item.camera,online:false,cached:true}));}});
window.bridge.on('bridge:state',data=>{bridgeState=data;if(!data.connected||selectedMac&&!data.cameras.find(c=>c.mac===selectedMac)?.online)baselinePending=false;if(selectedMac&&!data.cameras.some(c=>c.mac===selectedMac)){selectedMac='';draft=null;frame=null;clearFrame();}if(!selectedMac&&data.cameras.length)selectCamera(data.cameras[0].mac);else renderShell();});window.bridge.on('bridge:network-event',e=>{const detail=e.detail?` (${e.detail.replaceAll('_',' ')})`:'';if(e.status==='connected')toast(`${e.service} connected and saved on the bridge${detail}`);else if(e.status==='failed')toast(`${e.service} connection failed${detail}. Previous settings restored.`,true);else if(e.status==='disconnected')toast(`${e.service} disconnected${detail}`,true);});window.bridge.on('bridge:notice',m=>toast(m));window.bridge.on('bridge:error',m=>{if(receivingFrame){receivingFrame=false;setButtons();}toast(m,true);if(selectedMac)showOperation('Bridge error',m,'error');});window.bridge.on('bridge:request-result',result=>{if(result.mac!==selectedMac||result.kind!=='baseline')return;baselinePending=false;setButtons();showOperation(result.ok?'Baseline saved':'Baseline failed',`${result.reason} ${result.ok?'':`Bridge detail: ${result.raw}`}`,result.ok?'success':'error');if(result.ok)window.bridge.refresh().catch(()=>{});});window.bridge.on('bridge:frame',displayFrame);window.bridge.on('bridge:progress',p=>{if(p.mac===selectedMac)$('frame-progress').textContent=`Receiving ${Math.round(p.received/p.total*100)}%`;});window.bridge.on('bridge:state-event',event=>{const key=`${event.mac}:${event.id}`,previous=bridgeState.states[key]?.value;if(view==='monitor'&&changedKnownState(previous,event.value))playStateChime();bridgeState.states[key]=event;renderMonitor();});window.bridge.on('bridge:mqtt',event=>{mqttEvents.unshift(event);mqttEvents=mqttEvents.slice(0,80);if(view==='monitor')renderMonitor();});window.bridge.on('bridge:event',line=>{const p=line.split(' ');if(p[1]==='CONFIG_APPLIED')toast(`Camera ${p[2]} applied revision ${p[3]}. Capture a new empty baseline.`);if(p[1]==='CALIBRATION_SENSOR'&&p[2]===selectedMac)showOperation('Auto-sizing sensors',`Sensor ${p[3]} selected radius ${p[4]} px and threshold ${p[5]}; receiving the remaining results…`,'info');if(p[1]==='CALIBRATION_APPLIED'&&p[2]===selectedMac){calibrationPending=false;window.bridge.refresh().then(()=>setTimeout(()=>{if(selectedMac===p[2]){const selected=selectedId;draft=cloneConfig(bridgeState.configs[selectedMac]);selectedId=draft.cells.some(cell=>cell.id===selected)?selected:null;renderSetup();showOperation('Calibration saved',`The bridge stored revision ${p[3]}. Chosen radii and per-sensor thresholds are now displayed.`,'success');}},50)).catch(()=>{});}if(p[1]==='CALIBRATION_ERROR'&&p[2]===selectedMac){calibrationPending=false;setButtons();showOperation('Calibration failed','The bridge could not save the calibration results.','error');}if(p[1]==='MQTT_REMOVED'){mqttEvents=mqttEvents.filter(event=>event.topic!==p[2]);if(view==='monitor')renderMonitor();}});
window.bridge.on('bridge:cell-analysis',event=>{cellAnalyses.set(`${event.mac}:${event.id}`,event);if(event.mac===selectedMac&&event.id===selectedId){const cell=draft?.cells.find(item=>item.id===selectedId);if(cell)renderBaselineComparison(cell);}});
window.bridge.on('bridge:cell-state-event',event=>{bridgeState.cellStates ||= {};const key=`${event.mac}:${event.id}`,previous=bridgeState.cellStates[key]?.value;if(view==='setup'&&liveSensors&&event.mac===selectedMac&&changedKnownState(previous,event.value))playStateChime();bridgeState.cellStates[key]=event;if(liveSensors&&event.mac===selectedMac){drawOverlay();renderSensors();}});
window.bridge.on('bridge:request-result',result=>{if(result.mac===selectedMac&&result.kind==='config'){showOperation('Camera sync pending',result.reason,'info');toast(result.reason,true);}});
$('connect').addEventListener('click',event=>{if(!bridgeState.connected)return;event.stopImmediatePropagation();act(()=>window.bridge.disconnect());},true);
renderDiagnostics();renderViewer();scanPorts();setInterval(()=>{if(!bridgeState.connected&&!busy)scanPorts();},5000);setView('monitor');
